def test_partition_extension_and_flashback(self):
    table = self.validate_identity('SELECT * FROM "SH"."SALES" PARTITION(p1) s').find(exp.Table)
    self.assertIsInstance(table.args["partition"], exp.Partition)
    self.assertFalse(table.args["partition"].args.get("subpartition"))
    self.assertEqual(table.alias, "s")

    table = self.validate_identity("SELECT * FROM sales SUBPARTITION(sp1)").find(exp.Table)
    self.assertTrue(table.args["partition"].args.get("subpartition"))
    self.assertEqual(table.alias, "")

    self.validate_identity(
        "SELECT * FROM sales PARTITION (p1) s", "SELECT * FROM sales PARTITION(p1) s"
    )
    self.validate_identity("INSERT INTO sales PARTITION(p1) (col1) VALUES (1)")
    self.validate_identity("INSERT INTO sales PARTITION(p1) s (col1) VALUES (1)")
    self.validate_identity("INSERT INTO sales SUBPARTITION(sp1) s VALUES (1)")

    version = self.validate_identity("SELECT * FROM sales AS OF SCN 123456 s").find(
        exp.Version
    )
    self.assertEqual(version.name, "SCN")
    self.assertEqual(version.text("kind"), "AS OF")
    self.assertEqual(version.parent.alias, "s")

    version = self.validate_identity(
        "SELECT * FROM sales AS OF TIMESTAMP SYSTIMESTAMP - INTERVAL '1' HOUR s"
    ).find(exp.Version)
    self.assertEqual(version.name, "TIMESTAMP")
    self.assertIsInstance(version.expression, exp.Sub)

    self.validate_identity("SELECT * FROM sales PARTITION(p1) AS OF SCN 123456 s")
